<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gerando Holerites - VOKTAR</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#07090d;color:#f8fafc;font-family:Arial,sans-serif}.card{width:min(680px,calc(100% - 32px));padding:32px;border:1px solid #2a2f39;border-radius:18px;background:#15181e}.progress{height:18px;border-radius:999px;background:#252a33;overflow:hidden;margin:18px 0 12px}.bar{height:100%;width:0;background:linear-gradient(90deg,#f59e0b,#f97316);transition:width .25s}.row{display:flex;justify-content:space-between}.status{margin-top:22px;padding:14px;border-radius:12px;background:#20242c}.hidden{display:none}a,button{margin-top:22px;border:0;border-radius:10px;padding:12px 18px;font-weight:700;text-decoration:none;cursor:pointer}.primary{background:#16a34a;color:#fff}.secondary{background:#f59e0b;color:#111827}.error{color:#fca5a5}</style></head><body><div class="card"><h1>Gerando Holerites</h1><p>Folha #{{ $payrollRun->id }}. Processamento em pequenos lotes para evitar erro 504.</p><div class="progress"><div id="bar" class="bar"></div></div><div class="row"><strong id="percentage">0%</strong><span id="counter">Preparando...</span></div><div id="status" class="status">Iniciando.</div><a id="download" class="primary hidden" href="{{ $downloadUrl }}">Baixar ZIP dos Holerites</a><button id="restart" class="secondary hidden">Tentar novamente</button></div><script>
const processUrl=@json($processUrl),statusUrl=@json($statusUrl),restartUrl=@json($restartUrl);const bar=document.getElementById('bar'),percentage=document.getElementById('percentage'),counter=document.getElementById('counter'),statusBox=document.getElementById('status'),download=document.getElementById('download'),restart=document.getElementById('restart');let running=false;function render(d){let p=Number(d.percentage||0);bar.style.width=p+'%';percentage.textContent=p+'%';counter.textContent=(d.processed||0)+' de '+(d.total||0)+' processados';statusBox.textContent=d.message||'Processando...';statusBox.classList.toggle('error',d.status==='failed');download.classList.toggle('hidden',!d.download_ready);restart.classList.toggle('hidden',d.status!=='failed')}async function req(url){let r=await fetch(url,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}async function next(){if(running)return;running=true;try{let d=await req(processUrl);render(d);running=false;if(d.status==='processing')setTimeout(next,250)}catch(e){statusBox.textContent='Falha temporária: '+e.message+'. Tentando novamente...';statusBox.classList.add('error');running=false;setTimeout(next,2500)}}restart.onclick=async()=>{try{render(await req(restartUrl));next()}catch(e){statusBox.textContent=e.message}};(async()=>{try{let d=await req(statusUrl);render(d);if(d.status==='processing'||d.status==='not_started')next()}catch(e){statusBox.textContent=e.message;restart.classList.remove('hidden')}})();
</script></body></html>